\set ON_ERROR_STOP on
\pset pager off
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
SELECT now() AS database_snapshot_time, DATE '2026-10-31' AS review_date;
SELECT 'results' AS source,count(*),min(date),max(date) FROM results UNION ALL SELECT 'fixtures',count(*),min(date),max(date) FROM fixtures;
SELECT division,count(*),min(date),max(date),count(*) FILTER(WHERE "homeOddsAverage">1 AND "drawOddsAverage">1 AND "awayOddsAverage">1) AS priced,count(*) FILTER(WHERE date>='2023-10-31') AS recent FROM results GROUP BY division ORDER BY division;
SELECT count(*) AS rows, count(DISTINCT division) divisions, count(*) FILTER(WHERE "homeOddsAverage">1 AND "drawOddsAverage">1 AND "awayOddsAverage">1) complete_prices, count(*) FILTER(WHERE "homeOddsAverage"=0 AND "drawOddsAverage"=0 AND "awayOddsAverage"=0) no_prices,count(*) FILTER(WHERE "fullTimeResult" NOT IN('H','D','A') OR "fullTimeResult" IS NULL) invalid_outcomes,count(*) FILTER(WHERE "fullTimeResult" IS DISTINCT FROM CASE WHEN "fullTimeHomeGoals">"fullTimeAwayGoals" THEN 'H' WHEN "fullTimeHomeGoals"<"fullTimeAwayGoals" THEN 'A' ELSE 'D' END) inconsistent_outcome,count(*) FILTER(WHERE "fullTimeHomeGoals"<0 OR "fullTimeAwayGoals"<0) negative_goals,count(*) FILTER(WHERE "homeTeam"="awayTeam") same_team,count(*) FILTER(WHERE date<>date_trunc('day',date)) dates_with_time FROM results;
SELECT CASE WHEN date<'2005-07-01' THEN 'before 2005/06' WHEN date<'2019-07-01' THEN '2005/06 to 2018/19' WHEN date<'2023-07-01' THEN '2019/20 to 2022/23' ELSE '2023/24 onward' END era,count(*) total,count(*) FILTER(WHERE "homeOddsAverage">1 AND "drawOddsAverage">1 AND "awayOddsAverage">1) priced,count(*) FILTER(WHERE "homeOddsAverage"=0 AND "drawOddsAverage"=0 AND "awayOddsAverage"=0) missing,count(*) FILTER(WHERE ("homeOddsAverage">0 OR "drawOddsAverage">0 OR "awayOddsAverage">0) AND NOT ("homeOddsAverage">1 AND "drawOddsAverage">1 AND "awayOddsAverage">1)) incomplete_or_invalid FROM results GROUP BY 1 ORDER BY 1;
SELECT division,date,"homeTeam","awayTeam","homeOddsAverage","drawOddsAverage","awayOddsAverage" FROM results WHERE division='E0' AND date BETWEEN '2018-08-10' AND '2018-08-11' AND "homeTeam" IN('Man United','Bournemouth','Fulham');
SELECT count(*) fixtures,count(m."matchOddsId") analysed,count(*) FILTER(WHERE m."homeProbability"+m."drawProbability"+m."awayProbability">0) with_probs,count(*) FILTER(WHERE m.recommended IN('H','A')) strong_wins,count(*) FILTER(WHERE m."lowerRecommended" IN('H','A')) lower_wins_including_strong,count(*) FILTER(WHERE m.recommended='D' OR m."lowerRecommended"='D') draws,count(*) FILTER(WHERE m."valueSelection" IN('H','A')) value_wins,count(*) FILTER(WHERE f."homeOddsAverage">1 AND f."drawOddsAverage">1 AND f."awayOddsAverage">1) priced, min(m.calculated),max(m.calculated),count(*) FILTER(WHERE f.date>=DATE '2026-10-30') visible_date_eligible FROM fixtures f LEFT JOIN match_odds m USING("fixtureId");
WITH history AS (SELECT f."fixtureId",f.division,f."homeTeam",f."awayTeam",count(*) FILTER(WHERE r."homeTeam"=f."homeTeam") home_venue,count(*) FILTER(WHERE r."awayTeam"=f."awayTeam") away_venue,count(*) FILTER(WHERE r."homeTeam"=f."homeTeam" OR r."awayTeam"=f."homeTeam") home_total,count(*) FILTER(WHERE r."homeTeam"=f."awayTeam" OR r."awayTeam"=f."awayTeam") away_total FROM fixtures f LEFT JOIN results r ON r.division=f.division AND r.date<date_trunc('day',f.date) AND r.date>=date_trunc('day',f.date)-INTERVAL '6 years' GROUP BY f."fixtureId",f.division,f."homeTeam",f."awayTeam") SELECT count(*) total_fixtures,count(*) FILTER(WHERE home_venue>=10 AND away_venue>=10) eligible_10_venue,count(*) FILTER(WHERE home_total>=10 AND away_total>=10) eligible_10_total,count(*) FILTER(WHERE home_total>=5 AND away_total>=5) eligible_5_total,count(*) FILTER(WHERE home_total=0 OR away_total=0) missing_team_in_division,count(*) FILTER(WHERE home_total>0 AND away_total>0 AND (home_venue<10 OR away_venue<10)) both_known_fail_venue FROM history;
WITH history AS (SELECT f."fixtureId",f.division,f."homeTeam",f."awayTeam",count(*) FILTER(WHERE r."homeTeam"=f."homeTeam") home_venue,count(*) FILTER(WHERE r."awayTeam"=f."awayTeam") away_venue,count(*) FILTER(WHERE r."homeTeam"=f."homeTeam" OR r."awayTeam"=f."homeTeam") home_total,count(*) FILTER(WHERE r."homeTeam"=f."awayTeam" OR r."awayTeam"=f."awayTeam") away_total FROM fixtures f LEFT JOIN results r ON r.division=f.division AND r.date<date_trunc('day',f.date) AND r.date>=date_trunc('day',f.date)-INTERVAL '6 years' GROUP BY f."fixtureId",f.division,f."homeTeam",f."awayTeam") SELECT h.*,m."matchOddsId" IS NOT NULL AS stored_analysis FROM history h LEFT JOIN match_odds m USING("fixtureId") WHERE home_venue<10 OR away_venue<10 OR m."matchOddsId" IS NULL ORDER BY division,"homeTeam";
SELECT threshold,count(*) FILTER(WHERE greatest(m."homeProbability",m."awayProbability")>=threshold) AS win_candidates FROM (VALUES (0.50),(0.55),(0.60),(0.65),(0.70)) t(threshold) CROSS JOIN match_odds m GROUP BY threshold ORDER BY threshold;
SELECT count(*) AS accuracy_rows FROM accuracy;
SELECT count(*) AS calibration_rows FROM accuracy_calibration;
SELECT count(*) AS results_analysed,min(calculated),max(calculated),count(*) FILTER(WHERE abs("homeProbability"+"drawProbability"+"awayProbability"-1)>0.00001) invalid_probability_sum FROM result_match_odds;
SELECT (CASE WHEN extract(month FROM date)>=7 THEN extract(year FROM date)::int ELSE extract(year FROM date)::int-1 END) season_start,count(*) FILTER(WHERE "halfTimeResult" IS NULL OR "halfTimeResult"='') missing_half_time,count(*) FILTER(WHERE "halfTimeHomeGoals">"fullTimeHomeGoals" OR "halfTimeAwayGoals">"fullTimeAwayGoals") inconsistent_half_time FROM results GROUP BY 1 HAVING count(*) FILTER(WHERE "halfTimeResult" IS NULL OR "halfTimeResult"='')>0 OR count(*) FILTER(WHERE "halfTimeHomeGoals">"fullTimeHomeGoals" OR "halfTimeAwayGoals">"fullTimeAwayGoals")>0 ORDER BY 1;
COMMIT;
